#include <hip/hip_runtime.h>
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <stdexcept>
#include <thread>
#include <vector>
void check(hipError_t x){if(x!=hipSuccess)throw std::runtime_error(hipGetErrorString(x));}
__global__ void products(const uint32_t* a,const uint32_t* b,uint32_t* out,unsigned count){
 const unsigned i=blockIdx.x*blockDim.x+threadIdx.x;if(i>=count)return;
 float low,high;
 asm("v_fma_mix_f32 %0, %1, %2, 0 op_sel:[0,0,0] op_sel_hi:[1,1,0]" : "=v"(low) : "v"(a[i]),"v"(b[i]));
 asm("v_fma_mix_f32 %0, %1, %2, 0 op_sel:[1,1,0] op_sel_hi:[1,1,0]" : "=v"(high) : "v"(a[i]),"v"(b[i]));
 out[2u*i]=__float_as_uint(low);out[2u*i+1u]=__float_as_uint(high);
}
float value(uint16_t half){
 if(!(half&0x7fffu))return 0.0f;
 const uint32_t word=(uint32_t(half&0x8000u)<<16u)|((uint32_t((half>>10u)&31u)+112u)<<23u)|(uint32_t(half&1023u)<<13u);
